#!/usr/bin/env python3
from pwn import *

def extract_test_funcs(binary_path):
    elf = ELF(binary_path)

    test_funcs = []
    for name in elf.symbols:
        if 'test' in name.lower() or 'check' in name.lower():
            addr = elf.symbols[name]
            if addr:
                test_funcs.append((name, addr))

    return test_funcs

def dump_function_data(binary_path, func_name, func_addr):
    r = process(['r2', '-q', '-c', f'pdb @ {func_addr}', binary_path])
    output = r.recvall().decode('utf-8', errors='ignore')
    r.close()
    return output

def main():
    binary = "/home/ctfplayer/ctf_files/main.test"
    test_funcs = extract_test_funcs(binary)

    print(f"Found {len(test_funcs)} test/check functions:")
    for name, addr in test_funcs:
        print(f"\n=== Function: {name} @ {hex(addr)} ===")
        data = dump_function_data(binary, name, addr)
        print(data)

if __name__ == "__main__":
    main()

