from pwn import *
import string
import itertools

def test_input(input_str, path="/caterpillar"):
    # Create new connection for each test
    conn = remote("rev.chal.csaw.io", 7070)
    # Format gopher request
    request = f"{path}\t{input_str}\r\n"
    conn.send(request.encode())
    response = conn.recv()
    conn.close()
    return response

def test_butterfly(input_str):
    return test_input(input_str, "/butterfly")

def print_hex(data, msg=""):
    log.info(f"{msg}\nHex dump: {hexdump(data)}")

def run_test_case(input_str, description=""):
    log.info(f"\nTesting: {description}")
    log.info(f"Input: {repr(input_str)}")

    try:
        caterpillar_resp = test_input(input_str)
        print_hex(caterpillar_resp, "Caterpillar response:")

        try:
            butterfly_resp = test_butterfly(input_str)
            print_hex(butterfly_resp, "Butterfly response:")
        except:
            log.error("Butterfly test failed")

    except Exception as e:
        log.error(f"Test failed: {str(e)}")

# Test cases
def run_tests():
    # Test 1: Basic flag format
    run_test_case("flag{", "Basic flag format")

    # Test 2: 11-byte patterns
    test_patterns = [
        "ABCDEFGHIJK",
        "flag{123456}",
        "a" * 11,
        "0123456789a",
    ]

    for pattern in test_patterns:
        run_test_case(pattern, f"11-byte pattern: {pattern}")

    # Test 3: Control characters + flag{
    for i in range(0, 32, 4):  # Test fewer control chars to reduce noise
        test_str = chr(i) + "flag{"
        run_test_case(test_str, f"Control char 0x{i:02x} + flag{{")

    # Test 4: Mathematical constants based patterns
    math_patterns = {
        "pi": "31415926535",
        "e": "27182818284",
        "phi": "16180339887"
    }

    for name, pattern in math_patterns.items():
        run_test_case(pattern, f"Math constant {name}: {pattern}")

    # Test 5: Custom 11-byte flag-like patterns
    flag_patterns = [
        "flag{ABCDEF}",
        "flag{12345}",
        "flag{!@#$%}"
    ]

    for pattern in flag_patterns:
        if len(pattern) == 11:
            run_test_case(pattern, f"Flag pattern: {pattern}")

if __name__ == "__main__":
    run_tests()

